  'motors.bidirectional': { label: 'DShot hai chiều (đọc RPM)', help: 'ESC phải chạy firmware có bidirectional DShot (BLHeli_32 từ 32.7, Bluejay, AM32). Dòng trạng thái dưới bảng motor cho biết từng ESC có trả lời không.' },
  'motors.ext_pullup': { label: 'Có điện trở kéo lên ngoài', help: 'DShot hai chiều: bật khi dây tín hiệu motor đã có điện trở kéo lên 3,3 V trên mạch (thường 1 đến 4,7 kΩ). Khi đó firmware tắt điện trở kéo lên bên trong chân (~45 kΩ). Có hiệu lực sau khi lưu và khởi động lại.' },
  'motors.edt': { label: 'Extended DShot telemetry', help: 'Điện áp, dòng, nhiệt độ từ ESC. Cần DShot hai chiều. Firmware tự bật chức năng này trên ESC khi ESC bắt đầu trả lời (lúc cắm pin), không bao giờ bật khi đang arm.' },
  'motors.stall_disarm': { label: 'Disarm khi một motor dừng', help: 'Cánh chạm vật, motor bị kẹt hay mất đồng bộ: motor đang được ra lệnh quay mà tốc độ tụt xuống thì tắt hết motor, trước khi các motor còn lại lật máy xuống đất hoặc motor kẹt bị cháy. Mặc định tắt.' },
  'motors.stall_min_rpm': { label: 'Coi là dừng dưới', unit: 'rpm' },
