  'nav.ekf': { label: 'EKF', help: 'OFF: không chạy. SHADOW: chạy song song, chỉ ghi log (mặc định). NAV: Position Hold và GPS Rescue lấy vị trí, vận tốc, hướng mũi từ EKF khi nó có GPS.' },
